# ---------------------------------------------------------------- helpers


class FakeRunner(dc.Runner):
    """git runs for real; every other tool answers from `fakes` or is absent."""

    def __init__(self, fakes: dict[str, object] | None = None) -> None:
        self.fakes = dict(fakes or {})
        self.calls: list[list[str]] = []

    def run(self, argv, cwd=None, timeout=30):  # type: ignore[override]
        self.calls.append(list(argv))
        tool = argv[0]
        if tool in self.fakes:
            v = self.fakes[tool]
            return v(argv, cwd) if callable(v) else v  # type: ignore[operator]
        if tool == "git":
            return super().run(argv, cwd, timeout)
        return (127, "")


GOOD_LSOF = (0, "p1\nn/\n")


def write(path: Path, size: int = 50_000, age_days: float = 0.0) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(b"x" * size)
    if age_days:
        t = time.time() - age_days * 86400
        os.utime(path, (t, t))
    return path


def blocks(path: Path) -> int:
    return os.lstat(path).st_blocks * 512


def git(cwd: Path, *args: str) -> str:
    r = subprocess.run(["git", "-C", str(cwd), *args], check=True, capture_output=True, text=True)
    return r.stdout.strip()


def cells(s: str) -> int:
    n = 0
    for ch in s:
        if unicodedata.combining(ch) or ch == "️":
            continue
        n += 2 if (unicodedata.east_asian_width(ch) in "WF" or ord(ch) >= 0x1F300) else 1
    return n


def make_env(home: Path, runner=None, platform="darwin", roots=None, later=LATER, **kw):
    return dc.Env(
        home=home,
        platform=platform,
        runner=runner or FakeRunner({"lsof": GOOD_LSOF}),
        roots=list(roots or []),
        now=time.time() + later,
        user="tester",
        uid=501,
        **kw,
    )


