def add_wt(app: Path, name: str, branch: str | None = "auto", detach=False) -> Path:
    wt = app / ".worktrees" / name
    if detach:
        git(app, "worktree", "add", "--detach", str(wt), "main")
    else:
        git(app, "worktree", "add", "-b", name if branch == "auto" else branch, str(wt), "main")
    return wt


def commit_in(wt: Path, fname: str = "f.txt") -> str:
    write(wt / fname, 20)
    git(wt, "add", "-A")
    git(wt, "commit", "-m", f"work {fname}")
    return git(wt, "rev-parse", "HEAD")


def by_id(inv, prefix: str):
    hits = [i for i in inv.items if i.id.startswith(prefix)]
    assert hits, f"no item {prefix}: {[i.id for i in inv.items]}"
    return hits[0]


# ---------------------------------------------------------------- measure


def test_measure_uses_allocated_blocks_and_counts_hardlinks_once(tmp_path):
    d = tmp_path / "d"
    a = write(d / "a", 100_000)
    os.link(a, d / "b")
    write(d / "sub" / "c", 30_000)
    expected = blocks(a) + blocks(d / "sub" / "c") + blocks(d) + blocks(d / "sub")
    got = dc.measure(d)
    # directories carry a block or two on some filesystems; files must match exactly
    assert blocks(a) + blocks(d / "sub" / "c") <= got <= expected


def test_measure_never_follows_symlinks(tmp_path):
    outside = tmp_path / "outside"
    write(outside / "big", 400_000)
    d = tmp_path / "d"
    d.mkdir()
    (d / "link").symlink_to(outside)
    assert dc.measure(d) < blocks(outside / "big")


