def test_render_shape_and_width(home, capsys):
    write(home / ".npm" / "_cacache" / "x", 60_000)
    write(home / "Library" / "Caches" / "ms-playwright" / "c" / "b", 60_000)
    write(home / ".claude" / "projects" / "p" / "s.jsonl", 70_000)
    rc, out = run_main(["--home", str(home), "--platform", "darwin"], capsys)
    for word in ("SAFE", "REGENERABLE", "ASK FIRST", "free"):
        assert word in out
    assert "▓" in out and "░" in out
    for line in out.splitlines():
        if line.startswith("    $ "):
            continue  # copy-paste commands are never wrapped or cut
        assert cells(line) <= 76, f"{cells(line)} cells: {line!r}"
    for bad in ("—", "–", "--"):
        assert bad not in out.replace("--apply", "").replace("--only", "").replace("--tier", "")


def test_json_output_is_parseable(home, capsys):
    write(home / ".npm" / "_cacache" / "x", 60_000)
    rc, out = run_main(["--home", str(home), "--platform", "darwin", "--json"], capsys)
    data = json.loads(out)
    assert data["items"][0]["tier"] == "safe"
    assert "estimate_bytes" in data["totals"]


def test_report_has_marker_and_refuses_to_overwrite_foreign_file(home, tmp_path, capsys):
    write(home / ".npm" / "_cacache" / "x", 60_000)
    rep = tmp_path / "report.txt"
    rc, _ = run_main(["--home", str(home), "--platform", "darwin", "--report", str(rep)], capsys)
    assert rep.read_text().startswith(dc.REPORT_MARKER)
    rc2, _ = run_main(["--home", str(home), "--platform", "darwin", "--report", str(rep)], capsys)
    assert rc2 == 3  # overwriting its own report is fine
    foreign = tmp_path / "notes.md"
    foreign.write_text("hand written")
    rc3, _ = run_main(
        ["--home", str(home), "--platform", "darwin", "--report", str(foreign)], capsys
    )
    assert rc3 == 2
    assert foreign.read_text() == "hand written"


def test_ask_commands_never_force_and_park_detached_tips(repo, home):
    a = add_wt(repo, "unm2")
    commit_in(a)
    d = add_wt(repo, "det2", detach=True)
    commit_in(d)
    inv = dc.build_inventory(make_env(home, roots=[repo]))
    unm = wt_item(inv, a).ask_cmd
    det = wt_item(inv, d).ask_cmd
    assert "--force" not in unm and "--force" not in det
    assert "worktree remove" in unm
    assert "branch rescue/det2" in det and det.index("branch") < det.index("worktree remove")


def test_worktree_ask_commands_are_capped_in_text_output(repo, home, capsys):
    for n in range(dc.MAX_WORKTREE_COMMANDS + 3):
        commit_in(add_wt(repo, f"many{n}"))
    rc, out = run_main(["--home", str(home), "--platform", "darwin", "--root", str(repo)], capsys)
    shown = [x for x in out.splitlines() if x.startswith("    $ ") and "worktree remove" in x]
    assert len(shown) == dc.MAX_WORKTREE_COMMANDS
    assert "3 more worktree commands" in out


